func (s *Server) handleFactoryProductByID(w http.ResponseWriter, r *http.Request) {
	if !s.authorizeAdmin(r) {
		writeOpenAIError(w, http.StatusUnauthorized, "invalid admin token", "invalid_request_error", "invalid_api_key")
		return
	}
	rest := strings.Trim(strings.TrimPrefix(r.URL.Path, "/admin/factory/products/"), "/")
	if rest == "" {
		writeOpenAIError(w, http.StatusNotFound, "product id required", "invalid_request_error", "not_found")
		return
	}
	parts := strings.Split(rest, "/")
	key := strings.TrimSpace(parts[0])
	action := ""
	if len(parts) > 1 {
		action = strings.TrimSpace(parts[1])
	}
	switch r.Method {
	case http.MethodGet:
		p, ok, err := s.db.GetDataProduct(r.Context(), key)
		if err != nil {
			writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "get_failed")
			return
		writeOpenAIError(w, http.StatusUnauthorized, "invalid admin token", "invalid_request_error", "invalid_api_key")
		return
	}
	if r.Method != http.MethodGet {
		writeOpenAIError(w, http.StatusMethodNotAllowed, "method not allowed", "invalid_request_error", "method_not_allowed")
		return
	}

	// Aggregate dashboard KPIs from existing factory dashboard + dw tables.
	// A read the server could not complete is not an empty catalog: dropping these errors
	// published zeroes for every KPI below as a successful dashboard, so an unreachable table
	// looked the same as a factory with nothing in it. /assets and /funnel already answer 500
	// on the same reads.
	dash, err := s.db.FactoryDashboard(r.Context())
	if err != nil {
		writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "dashboard_failed")
		return
	}
	assets, err := s.db.ListDataAssets(r.Context())
	if err != nil {
		writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "dashboard_failed")
		return
	}
	products, err := s.db.ListDataProducts(r.Context(), "")
	if err != nil {
		writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "dashboard_failed")
		return
	}

	// Count products by status
	var published, review, riskHigh int
	for _, p := range products {
		switch p.Status {
		case "published":
			published++
		case "review", "risk_review":
			review++
		}
		if p.RiskScore >= 70 {
			riskHigh++
		}
	}

	// Top 10 products by revenue score
	top10 := products
	if len(top10) > 10 {
		top10 = top10[:10]
	}
	topProducts := make([]map[string]any, 0, len(top10))
	for _, p := range top10 {
		topProducts = append(topProducts, map[string]any{
			"product_key": p.ProductKey, "name": p.NameKO,
			"revenue_score": p.RevenueScore, "risk_score": p.RiskScore, "status": p.Status,
	if !s.authorizeAdmin(r) {
		writeOpenAIError(w, http.StatusUnauthorized, "invalid admin token", "invalid_request_error", "invalid_api_key")
		return
	}
	if r.Method != http.MethodGet {
		writeOpenAIError(w, http.StatusMethodNotAllowed, "method not allowed", "invalid_request_error", "method_not_allowed")
		return
	}
	// Same contract as /home: a failed read must not be reported as an empty portfolio with
	// zero averages.
	dash, err := s.db.FactoryDashboard(r.Context())
	if err != nil {
		writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "analytics_failed")
		return
	}
	products, err := s.db.ListDataProducts(r.Context(), "")
	if err != nil {
		writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "analytics_failed")
		return
	}

	var totalRevenue, totalRisk int
	statusCount := map[string]int{}
	for _, p := range products {
		totalRevenue += p.RevenueScore
		totalRisk += p.RiskScore
		statusCount[p.Status]++
	}
	avgRevenue := 0
	avgRisk := 0
	if len(products) > 0 {
		avgRevenue = totalRevenue / len(products)
		avgRisk = totalRisk / len(products)
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"analytics": map[string]any{
			"total_products":   len(products),
			"total_ideas":      dash.IdeasTotal,
			"avg_revenue":      avgRevenue,
			"avg_risk":         avgRisk,
			"status_breakdown": statusCount,
			"published":        statusCount["published"],
			"archived":         statusCount["archived"],
		},
	})
}

// handleDataWorksFunnel returns factory-to-revenue lifecycle counts.
func (s *Server) handleDataWorksFunnel(w http.ResponseWriter, r *http.Request) {
	if !s.authorizeAdmin(r) {
		writeOpenAIError(w, http.StatusUnauthorized, "invalid admin token", "invalid_request_error", "invalid_api_key")
		return
	}
	if r.Method != http.MethodGet {
		writeOpenAIError(w, http.StatusMethodNotAllowed, "method not allowed", "invalid_request_error", "method_not_allowed")
		return
	}
	dash, err := s.db.FactoryDashboard(r.Context())
	if err != nil {
		writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "funnel_failed")
		return
	}
	stages := []map[string]any{
		{"stage": "ideas", "count": dash.IdeasTotal},
		{"stage": "definition", "count": dash.DraftProducts + dash.ReviewProducts},
		{"stage": "risk_review", "count": dash.RiskReviewProducts},
		{"stage": "approved", "count": dash.ApprovedProducts},
		{"stage": "published", "count": dash.PublishedProducts},
	}
	writeJSON(w, http.StatusOK, map[string]any{"funnel": stages})
}

