func entitlementAllowsQuery(scope string) bool {
	if strings.TrimSpace(scope) == "" {
		return true
	}
	grants := strings.FieldsFunc(strings.ToLower(scope), func(r rune) bool {
		return r == ',' || r == ';' || r == '|' || r == ' ' || r == '\t' || r == '\n' || r == '\r'
