import os,json,socket,sqlite3,subprocess,time,urllib.request,urllib.error
from pathlib import Path
run=Path('/mnt/c/Users/USER/projects/aidev/state/runs/2026-10-08-122226-dataworks-improve')
with socket.socket() as sock:
    sock.bind(('127.0.0.1',0)); port=sock.getsockname()[1]
env={'PATH':os.environ['PATH'],'LISTEN_ADDR':f'127.0.0.1:{port}','DB_DRIVER':'sqlite','DB_DSN':str(run/'scout.db'),'LOG_FALLBACK_PATH':str(run/'scout-fallback.ndjson'),'ADMIN_TOKEN':'scout-local-only','GATEWAY_SECRET':'scout-isolated-local-secret','AUTH_ENABLED':'false','UPSTREAM_BASE_URL':'http://127.0.0.1:1'}
log=(run/'scout-server.log').open('w')
proc=subprocess.Popen([str(run/'scout-server')],cwd=run,env=env,stdout=log,stderr=log)
def get(path):
    req=urllib.request.Request(f'http://127.0.0.1:{port}'+path,headers={'Authorization':'Bearer [REDACTED_SECRET]'})
    try:
        with urllib.request.urlopen(req,timeout=3) as resp: return resp.status,json.load(resp)
    except urllib.error.HTTPError as e: return e.code,json.load(e)
results=[]
try:
    for _ in range(100):
        if proc.poll() is not None: raise RuntimeError('server exited')
        try: get('/healthz'); break
        except (OSError,ValueError): time.sleep(.1)
    paths=['/admin/factory/dashboard','/admin/dataworks/home','/admin/dataworks/analytics','/admin/dataworks/funnel']
    results.append({'case':'baseline','responses':{p:get(p) for p in paths}})
    db=sqlite3.connect(run/'scout.db')
    for table in ['data_products','product_risk_reviews','product_poc_plans']:
        db.execute(f'ALTER TABLE {table} RENAME TO scout_unavailable'); db.commit()
        try: results.append({'case':table+'_unavailable','responses':{p:get(p) for p in paths}})
        finally: db.execute(f'ALTER TABLE scout_unavailable RENAME TO {table}'); db.commit()
    db.execute('ALTER TABLE data_products RENAME TO scout_products_real')
    db.execute('CREATE VIEW data_products AS SELECT status FROM scout_products_real'); db.commit()
    try: results.append({'case':'average_query_only_missing_revenue_column','responses':{p:get(p) for p in [paths[0],paths[3]]}})
    finally:
        db.execute('DROP VIEW data_products'); db.execute('ALTER TABLE scout_products_real RENAME TO data_products'); db.commit()
    results.append({'case':'restored','responses':{p:get(p) for p in paths}})
    db.close()
    (run/'scout-reproduction.json').write_text(json.dumps(results,ensure_ascii=False,indent=2)+'\\n')
    for result in results:
        print(result['case'],{p:v[0] for p,v in result['responses'].items()})
finally:
    proc.terminate()
    try: proc.wait(timeout=20)
    except subprocess.TimeoutExpired: proc.kill(); proc.wait()
    log.close()
PY"

